@auth<div class="modal fade" id="productOrderModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content order-modal"><div class="modal-header"><div><span class="eyebrow">PRODUCT ORDER</span><h2 class="h5 mb-0" id="productOrderTitle"></h2></div><button class="btn-close" data-bs-dismiss="modal"></button></div><form id="productOrderForm" enctype="multipart/form-data"><div class="modal-body">@csrf<input type="hidden" name="product_id" id="productId"><input type="hidden" name="request_uid" id="productRequestUid"><div class="product-checkout-price"><span>Total from balance</span><strong id="productPrice"></strong></div><div class="mb-3" id="productDeviceWrap"><label class="form-label fw-bold">Device / IMEI / target</label><input class="form-control" name="device" id="productDevice"></div><div class="mb-3 d-none" id="productFileWrap"><label class="form-label fw-bold">Required file</label><input class="form-control" type="file" name="file" id="productFile"></div><div><label class="form-label fw-bold">Comments (optional)</label><textarea class="form-control" name="comments" rows="3"></textarea></div><div class="alert alert-danger d-none mt-3" id="productOrderError"></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-gsm" id="productOrderSubmit">Confirm & pay</button></div></form></div></div></div>
@push('scripts')<script>const pm=document.getElementById('productOrderModal'),pf=document.getElementById('productOrderForm');document.querySelectorAll('.js-buy-product').forEach(b=>b.addEventListener('click',()=>{const p=JSON.parse(b.dataset.product);document.getElementById('productId').value=p.id;document.getElementById('productRequestUid').value=crypto.randomUUID();document.getElementById('productOrderTitle').textContent=p.name;document.getElementById('productPrice').textContent='$'+Number(p.price).toFixed(2);document.getElementById('productDevice').required=p.device;document.getElementById('productDeviceWrap').classList.toggle('d-none',!p.device);document.getElementById('productFile').required=p.file;document.getElementById('productFileWrap').classList.toggle('d-none',!p.file);document.getElementById('productOrderError').classList.add('d-none');bootstrap.Modal.getOrCreateInstance(pm).show()}));pf.addEventListener('submit',async e=>{e.preventDefault();const btn=document.getElementById('productOrderSubmit'),err=document.getElementById('productOrderError');btn.disabled=true;const r=await fetch(@json(route('customer.product-orders.store')),{method:'POST',body:new FormData(pf),headers:{Accept:'application/json'}}),j=await r.json().catch(()=>({}));btn.disabled=false;if(r.ok){location.href=@json(route('customer.orders.type','product'));return}err.textContent=j.message||Object.values(j.errors||{}).flat().join(' ');err.classList.remove('d-none')})</script>@endpush @endauth
